ALTER TABLE public.items ADD COLUMN branch_id text NOT NULL DEFAULT 'B1' REFERENCES public.branches(id);
ALTER TABLE public.sales ADD COLUMN branch_id text NOT NULL DEFAULT 'B1' REFERENCES public.branches(id);
ALTER TABLE public.loans ADD COLUMN branch_id text NOT NULL DEFAULT 'B1' REFERENCES public.branches(id);
ALTER TABLE public.loan_payments ADD COLUMN branch_id text NOT NULL DEFAULT 'B1' REFERENCES public.branches(id);
CREATE INDEX items_branch ON public.items(branch_id); CREATE INDEX sales_branch ON public.sales(branch_id,date); CREATE INDEX loans_branch ON public.loans(branch_id); CREATE INDEX payments_branch ON public.loan_payments(branch_id,date);
CREATE FUNCTION public.staff_can(permission text, target_branch text DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.staff_access a JOIN public.staff_roles r ON r.id=a.role_id WHERE a.user_id=auth.uid() AND a.active AND permission=ANY(r.permissions) AND (target_branch IS NULL OR target_branch=ANY(a.branch_ids)) AND (target_branch IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=target_branch AND b.active))) $$;
REVOKE ALL ON FUNCTION public.staff_can(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.staff_can(text,text) TO authenticated;
DROP POLICY items_read ON public.items; CREATE POLICY items_read ON public.items FOR SELECT TO authenticated USING(public.staff_can('View stock',branch_id));
DROP POLICY costs_admin ON public.item_costs; CREATE POLICY costs_admin ON public.item_costs FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.items i WHERE i.id=item_id AND public.staff_can('View costs and profit',i.branch_id)));
DROP POLICY customers_read ON public.customers; CREATE POLICY customers_read ON public.customers FOR SELECT TO authenticated USING(public.staff_can('View customers'));
DROP POLICY sales_read ON public.sales; CREATE POLICY sales_read ON public.sales FOR SELECT TO authenticated USING(public.staff_can('View reports',branch_id) OR public.staff_can('Create bills',branch_id) OR public.staff_can('View customers',branch_id) OR public.staff_can('Collect repayments',branch_id));
DROP POLICY sale_cost_admin ON public.sale_costs; CREATE POLICY sale_cost_admin ON public.sale_costs FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.sale_items l JOIN public.sales s ON s.id=l.sale_id WHERE l.id=sale_item_id AND public.staff_can('View costs and profit',s.branch_id)));
DROP POLICY loans_read ON public.loans; CREATE POLICY loans_read ON public.loans FOR SELECT TO authenticated USING(public.staff_can('Collect repayments') OR public.staff_can('View customers',branch_id) OR public.staff_can('View reports',branch_id));
DROP POLICY installments_read ON public.loan_installments; CREATE POLICY installments_read ON public.loan_installments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.loans l WHERE l.id=loan_id));
DROP POLICY payments_read ON public.loan_payments; CREATE POLICY payments_read ON public.loan_payments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.loans l WHERE l.id=loan_id));
DROP POLICY suppliers_read ON public.suppliers; CREATE POLICY suppliers_read ON public.suppliers FOR SELECT TO authenticated USING(public.staff_can('View stock') OR public.staff_can('Manage suppliers'));
DROP POLICY suppliers_insert ON public.suppliers; CREATE POLICY suppliers_insert ON public.suppliers FOR INSERT TO authenticated WITH CHECK(public.staff_can('Manage suppliers'));
DROP POLICY suppliers_update ON public.suppliers; CREATE POLICY suppliers_update ON public.suppliers FOR UPDATE TO authenticated USING(public.staff_can('Manage suppliers')) WITH CHECK(public.staff_can('Manage suppliers'));
CREATE FUNCTION public.save_branch(p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Owner access required'; END IF; IF nullif(trim(p->>'name'),'') IS NULL OR nullif(trim(p->>'code'),'') IS NULL THEN RAISE EXCEPTION 'Branch name and code required'; END IF; IF NOT coalesce((p->>'active')::boolean,true) AND EXISTS(SELECT 1 FROM public.items WHERE branch_id=p->>'id' AND status='In Stock') THEN RAISE EXCEPTION 'Transfer remaining stock before deactivating this branch'; END IF; INSERT INTO public.branches(id,code,name,address,phone,active) VALUES(p->>'id',upper(trim(p->>'code')),trim(p->>'name'),coalesce(p->>'address',''),coalesce(p->>'phone',''),coalesce((p->>'active')::boolean,true)) ON CONFLICT(id) DO UPDATE SET name=excluded.name,code=excluded.code,address=excluded.address,phone=excluded.phone,active=excluded.active; END $$;
CREATE FUNCTION public.save_staff_role(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid:=coalesce(nullif(p->>'id','')::uuid,gen_random_uuid()); perms text[]; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Owner access required'; END IF; IF nullif(trim(p->>'name'),'') IS NULL OR lower(trim(p->>'name'))='super admin' THEN RAISE EXCEPTION 'Choose a valid custom role name'; END IF; SELECT coalesce(array_agg(value),'{}') INTO perms FROM jsonb_array_elements_text(p->'permissions'); IF NOT perms <@ ARRAY['View dashboard','Create bills','View stock','Manage stock','Collect repayments','View customers','View costs and profit','View reports','Manage suppliers','Manage categories','Manage users','Manage roles','Manage settings','Transfer stock']::text[] THEN RAISE EXCEPTION 'Unknown permission'; END IF; INSERT INTO public.staff_roles(id,name,permissions) VALUES(rid,trim(p->>'name'),perms) ON CONFLICT(id) DO UPDATE SET name=excluded.name,permissions=excluded.permissions; RETURN rid; END $$;
CREATE FUNCTION public.save_staff_access(p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=(p->>'user_id')::uuid; bs text[]; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Owner access required'; END IF; IF uid=auth.uid() OR public.has_role(uid,'admin') THEN RAISE EXCEPTION 'Owner access cannot be changed here'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=uid) THEN RAISE EXCEPTION 'Staff account not found'; END IF; SELECT coalesce(array_agg(value),'{}') INTO bs FROM jsonb_array_elements_text(p->'branch_ids'); IF cardinality(bs)=0 OR EXISTS(SELECT 1 FROM unnest(bs) b WHERE NOT EXISTS(SELECT 1 FROM public.branches WHERE id=b AND active)) THEN RAISE EXCEPTION 'Select active branches'; END IF; INSERT INTO public.staff_access(user_id,role_id,branch_ids,active) VALUES(uid,(p->>'role_id')::uuid,bs,coalesce((p->>'active')::boolean,false)) ON CONFLICT(user_id) DO UPDATE SET role_id=excluded.role_id,branch_ids=excluded.branch_ids,active=excluded.active; IF nullif(trim(p->>'display_name'),'') IS NOT NULL THEN UPDATE public.profiles SET display_name=trim(p->>'display_name') WHERE id=uid; END IF; END $$;
CREATE FUNCTION public.branch_transaction_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b text:=coalesce(nullif(current_setting('app.branch_id',true),''),'B1'); BEGIN IF TG_OP='INSERT' THEN NEW.branch_id:=b; END IF; IF TG_TABLE_NAME='items' THEN IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND NEW.status=OLD.status AND NEW.branch_id=OLD.branch_id) THEN IF NOT public.staff_can('Manage stock',NEW.branch_id) THEN RAISE EXCEPTION 'Stock management permission required'; END IF; END IF; ELSIF TG_TABLE_NAME='sales' THEN IF NOT public.staff_can('Create bills',b) THEN RAISE EXCEPTION 'Billing permission required'; END IF; IF EXISTS(SELECT 1 FROM public.items WHERE id IN(SELECT (x->>'id')::uuid FROM jsonb_array_elements(current_setting('app.sale_lines',true)::jsonb) x) AND branch_id<>b) THEN RAISE EXCEPTION 'All pieces must belong to the billing branch'; END IF; NEW.invoice_no:=b||'-'||NEW.invoice_no; ELSIF TG_TABLE_NAME='loans' THEN NEW.loan_no:=b||'-'||NEW.loan_no; ELSIF TG_TABLE_NAME='loan_payments' THEN IF NOT public.staff_can('Collect repayments',b) THEN RAISE EXCEPTION 'Collection permission required'; END IF; NEW.receipt_no:=b||'-'||NEW.receipt_no; END IF; RETURN NEW; END $$;
CREATE TRIGGER branch_items BEFORE INSERT OR UPDATE ON public.items FOR EACH ROW EXECUTE FUNCTION public.branch_transaction_guard(); CREATE TRIGGER branch_sales BEFORE INSERT ON public.sales FOR EACH ROW EXECUTE FUNCTION public.branch_transaction_guard(); CREATE TRIGGER branch_loans BEFORE INSERT ON public.loans FOR EACH ROW EXECUTE FUNCTION public.branch_transaction_guard(); CREATE TRIGGER branch_payments BEFORE INSERT ON public.loan_payments FOR EACH ROW EXECUTE FUNCTION public.branch_transaction_guard();
DO $$ DECLARE fn text; def text; BEGIN FOREACH fn IN ARRAY ARRAY['save_item','complete_sale','record_payment'] LOOP SELECT pg_get_functiondef(p.oid) INTO def FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=fn; def:=replace(def,'public.'||fn||'(', 'public.internal_'||fn||'('); IF fn='save_item' THEN def:=replace(def,'IF NOT public.has_role(auth.uid(),''admin'') THEN','IF NOT public.staff_can(''Manage stock'', coalesce(p->>''branch_id'',''B1'')) THEN'); END IF; EXECUTE def; EXECUTE format('REVOKE ALL ON FUNCTION public.internal_%I(jsonb) FROM PUBLIC,anon,authenticated',fn); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.save_item(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b text:=coalesce(p->>'branch_id','B1'); BEGIN IF NOT public.staff_can('Manage stock',b) THEN RAISE EXCEPTION 'Stock management permission required'; END IF; IF p->>'id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.items WHERE id=(p->>'id')::uuid AND branch_id=b) THEN RAISE EXCEPTION 'Piece does not belong to this branch'; END IF; PERFORM set_config('app.branch_id',b,true); RETURN public.internal_save_item(p); END $$;
CREATE OR REPLACE FUNCTION public.complete_sale(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b text:=coalesce(p->>'branch_id','B1'); BEGIN IF NOT public.staff_can('Create bills',b) THEN RAISE EXCEPTION 'Billing permission required'; END IF; PERFORM set_config('app.branch_id',b,true); PERFORM set_config('app.sale_lines',(p->'lines')::text,true); RETURN public.internal_complete_sale(p); END $$;
CREATE OR REPLACE FUNCTION public.record_payment(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b text:=coalesce(p->>'branch_id','B1'); BEGIN IF NOT public.staff_can('Collect repayments',b) THEN RAISE EXCEPTION 'Collection permission required'; END IF; PERFORM set_config('app.branch_id',b,true); RETURN public.internal_record_payment(p); END $$;
CREATE OR REPLACE FUNCTION public.delete_item(iid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b text; BEGIN SELECT branch_id INTO b FROM public.items WHERE id=iid AND status='In Stock' FOR UPDATE; IF b IS NULL OR NOT public.staff_can('Manage stock',b) THEN RAISE EXCEPTION 'Stock management permission required'; END IF; DELETE FROM public.items WHERE id=iid; END $$;
CREATE FUNCTION public.transfer_stock(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i record; dest text:=p->>'to_branch'; mid uuid; BEGIN SELECT * INTO i FROM public.items WHERE id=(p->>'item_id')::uuid FOR UPDATE; IF NOT FOUND OR i.status<>'In Stock' THEN RAISE EXCEPTION 'Only in-stock pieces can be transferred'; END IF; IF i.branch_id<>p->>'from_branch' THEN RAISE EXCEPTION 'Piece has already moved'; END IF; IF dest=i.branch_id OR NOT EXISTS(SELECT 1 FROM public.branches WHERE id=dest AND active) THEN RAISE EXCEPTION 'Choose another active branch'; END IF; IF NOT public.staff_can('Transfer stock',i.branch_id) THEN RAISE EXCEPTION 'Transfer permission required'; END IF; INSERT INTO public.stock_movements(item_id,from_branch,to_branch,internal_tag,system_tag,note,performed_by) VALUES(i.id,i.branch_id,dest,i.tag_id,i.system_tag,coalesce(p->>'note',''),auth.uid()) RETURNING id INTO mid; UPDATE public.items SET branch_id=dest WHERE id=i.id; RETURN mid; END $$;
REVOKE ALL ON FUNCTION public.save_branch(jsonb),public.save_staff_role(jsonb),public.save_staff_access(jsonb),public.transfer_stock(jsonb),public.branch_transaction_guard() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_branch(jsonb),public.save_staff_role(jsonb),public.save_staff_access(jsonb),public.transfer_stock(jsonb) TO authenticated;